import assert from 'node:assert/strict';import {chromium} from 'playwright-core';
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--enable-webgl','--ignore-gpu-blocklist','--use-angle=metal']});try{const page=await browser.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:5277/qa/exo-motion-crossrig-audit-20261102.html?clip='+String(process.env.EXO_MOTION_SOURCE==='v6e'?'v6e':'v3'),{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>window.__exoCrossRigAudit!==null,null,{timeout:60000});const output=await page.evaluate(()=>window.__exoCrossRigAudit);console.log('EXO_CROSSRIG_RESEARCH',JSON.stringify({output,errors},null,2));assert.equal(output.length,5);assert.deepEqual(errors,[])}finally{await browser.close()}
